mapper.select:
select count(*) from creator_earning_ledger
 where creator_member_id = #{creatorId} and actor_member_id = #{actorId}
   and item_kind = #{itemKind} and item_ref = #{itemRef}
   and occur_date = #{day} and event_type = 'PLAY' and points > 0

select id, event_type as eventType, item_kind as itemKind, item_ref as itemRef, item_title as itemTitle,
       points, capped, creator_minor as creatorMinor, currency, money_state as moneyState, occur_time as occurTime
  from creator_earning_ledger
 where creator_member_id = #{creatorId}
    and id < #{before}
 order by id desc
 limit #{limit}

select e.creator_member_id as creatorId, max(m.nickname) as nickname, count(distinct concat(e.item_kind, ':', e.item_ref)) as items, sum(case when e.event_type in ('ADOPT', 'INSTALL') then 1 else 0 end) as uses, sum(case when e.event_type = 'PLAY' then 1 else 0 end) as plays, sum(case when e.event_type = 'PLAY' and e.capped = 1 then 1 else 0 end) as cappedPlays, sum(e.points) as points, sum(case when e.event_type = 'SALE' then 1 else 0 end) as sales, sum(case when e.event_type in ('SALE', 'SALE_REVERSAL') then e.creator_minor else 0 end) as heldCreatorMinor, max(e.occur_time) as lastAt from creator_earning_ledger e left join ums_member m on m.id = e.creator_member_id
and e.creator_member_id = #{creatorId} and e.occur_time >= #{from} and e.occur_time < #{to}
group by e.creator_member_id order by sum(e.points) desc, e.creator_member_id

select id, event_key as eventKey, event_type as eventType, creator_member_id as creatorId, actor_member_id as actorId, item_kind as itemKind, item_ref as itemRef, item_title as itemTitle, source_ref as sourceRef, points, capped, gross_minor as grossMinor, creator_share_bps as shareBps, creator_minor as creatorMinor, currency, money_state as moneyState, occur_time as occurTime, create_time as createTime from creator_earning_ledger
and creator_member_id = #{creatorId} and event_type = #{eventType}
order by id desc
